const dsaCases = {
    Arrays: {
        hints: ["Write down the index invariant before moving pointers or changing the array.", "Check empty, one-element, duplicate, and boundary-window inputs before optimizing.", "State whether the algorithm mutates input and account for auxiliary space."],
        items: [
            ["Easy", "Find the second-largest distinct value", "Implement secondLargest(numbers) in one pass. Return the second-largest distinct finite number, or null when fewer than two distinct values exist. Do not sort or mutate the input array.", "[4, 9, 2, 9, 7] => 7.", "[] and [5,5] => null; negative values are allowed.", "function secondLargest(a) { let first = -Infinity, second = -Infinity; for (const n of a) { if (!Number.isFinite(n)) continue; if (n > first) { second = first; first = n; } else if (n < first && n > second) second = n; } return second === -Infinity ? null : second; }", "O(n) time, O(1) extra space.", "Track the largest and second-largest distinct values; skip equality with the current maximum.", "After each item, first and second are the two largest distinct values seen so far."],
            ["Easy", "Move zeroes to the end stably", "Write moveZeroes(numbers) that moves numeric zeroes to the end while preserving the relative order of all non-zero entries. Return a new array and do not mutate the input.", "[0, 3, 0, -2, 5] => [3, -2, 5, 0, 0].", "[] remains []; an array containing only zeroes keeps the same length.", "function moveZeroes(a) { const nonzero = a.filter((value) => value !== 0); return [...nonzero, ...Array(a.length - nonzero.length).fill(0)]; }", "O(n) time and O(n) output space.", "Collect non-zero values in encounter order, then append the required number of zeroes.", "filter preserves the relative order and the input remains unchanged."],
            ["Easy", "Build prefix sums for range queries", "Implement prefixSums(values) so each inclusive range sum can be answered in constant time after preprocessing. Define rangeSum(prefix,left,right) and validate that the requested indices form an in-bounds range.", "[2, -1, 4] gives prefix [0,2,1,5]; sum 0..2 is 5.", "An empty source has prefix [0]; any range query on it is invalid.", "function prefixSums(a) { const p = [0]; for (const value of a) p.push(p.at(-1) + value); return p; }\nfunction rangeSum(p, left, right) { if (left < 0 || right < left || right + 1 >= p.length) throw new RangeError('Invalid range'); return p[right + 1] - p[left]; }", "O(n) preprocessing time and O(1) per range query.", "Store a leading zero so a range beginning at index zero needs no special case.", "The difference prefix[right+1] - prefix[left] includes both endpoints."],
            ["Medium", "Rotate an array by k positions", "Implement rotateRight(values,k) to return a new array rotated right by k places. Support k larger than the array length and negative k as a left rotation; do not use repeated single-step rotations.", "[1,2,3,4,5], k=2 => [4,5,1,2,3].", "[] with any k returns []; k=-1 gives [2,3,4,1] for [1,2,3,4].", "function rotateRight(a, k) { if (!a.length) return []; const shift = ((k % a.length) + a.length) % a.length; if (shift === 0) return [...a]; return [...a.slice(-shift), ...a.slice(0, -shift)]; }", "O(n) time and O(n) output space.", "Normalize k into [0,n) with a double modulo so negative values work.", "Split once at n-shift and concatenate suffix before prefix."],
            ["Medium", "Merge two sorted arrays without losing duplicates", "Implement mergeSorted(a,b) for ascending numeric arrays. Return a new sorted array containing every occurrence, and use two pointers rather than concatenating and sorting.", "[1,2,2] and [2,3] => [1,2,2,2,3].", "Either input can be empty; equal values from both inputs are all preserved.", "function mergeSorted(a, b) { const out = []; let i = 0, j = 0; while (i < a.length && j < b.length) out.push(a[i] <= b[j] ? a[i++] : b[j++]); return out.concat(a.slice(i), b.slice(j)); }", "O(n+m) time and O(n+m) output space.", "Compare current heads and advance exactly one pointer on each append.", "Once one side is exhausted, append the remaining sorted suffix."],
            ["Medium", "Find the shortest subarray meeting a sum", "For a positive-integer array and target, implement minLengthAtLeast(target,values) using a sliding window. Return the minimum length with sum >= target, or 0 when impossible.", "target=7, [2,3,1,2,4,3] => 2.", "An empty array or target larger than total sum returns 0.", "function minLengthAtLeast(target, a) { let left = 0, sum = 0, best = Infinity; for (let right = 0; right < a.length; right++) { sum += a[right]; while (sum >= target) { best = Math.min(best, right - left + 1); sum -= a[left++]; } } return best === Infinity ? 0 : best; }", "O(n) time and O(1) auxiliary space because positive values make the window monotone.", "Expand right to reach the target, then shrink left while the condition remains true.", "Each pointer advances at most n times, so the nested while loop remains linear overall."],
            ["Hard", "Find all unique triplets summing to zero", "Implement threeSum(values) returning every unique value-triplet whose sum is zero. Sort a copy, use a fixed index plus two pointers, and avoid duplicate triplets without mutating the input.", "[-1,0,1,2,-1,-4] => [[-1,-1,2],[-1,0,1]].", "[0,0,0,0] returns exactly [[0,0,0]]; fewer than three values returns [].", "function threeSum(a) { const s = [...a].sort((x,y) => x-y), out = []; for (let i=0;i<s.length-2;i++) { if (i && s[i]===s[i-1]) continue; let l=i+1,r=s.length-1; while(l<r) { const sum=s[i]+s[l]+s[r]; if(sum===0) { out.push([s[i],s[l],s[r]]); const x=s[l], y=s[r]; while(s[l]===x) l++; while(s[r]===y) r--; } else if(sum<0) l++; else r--; } } return out; }", "O(n²) time and O(n) space for the sorted copy and output.", "After sorting, fix one value and move the two pointers according to the sum sign.", "Skip duplicate anchors and duplicate pointer values after recording each valid triplet."],
            ["Hard", "Compute product except self without division", "Implement productExceptSelf(values) with O(n) time and no division. Return an array where each position is the product of every other value; handle zeroes naturally.", "[1,2,3,4] => [24,12,8,6].", "[0,2,0] => [0,0,0]; one value returns [1].", "function productExceptSelf(a) { const out = Array(a.length).fill(1); let prefix = 1; for(let i=0;i<a.length;i++){out[i]=prefix;prefix*=a[i];} let suffix=1; for(let i=a.length-1;i>=0;i--){out[i]*=suffix;suffix*=a[i];} return out; }", "O(n) time and O(1) extra space excluding the output array.", "Store exclusive prefix products in the output, then multiply exclusive suffix products in reverse.", "No division is needed, and zero handling follows from multiplication."],
            ["Hard", "Find the maximum product subarray", "Implement maxProductSubarray(values) for a non-empty array of integers. Track both maximum and minimum products ending at each index because a negative value can swap their roles.", "[2,3,-2,4] => 6; [-2,0,-1] => 0.", "A single negative value returns that value; an empty list is rejected.", "function maxProductSubarray(a) { if (!a.length) throw new RangeError('Expected non-empty array'); let hi=a[0], lo=a[0], best=a[0]; for(let i=1;i<a.length;i++){ const x=a[i]; if(x<0) [hi,lo]=[lo,hi]; hi=Math.max(x,hi*x); lo=Math.min(x,lo*x); best=Math.max(best,hi); } return best; }", "O(n) time and O(1) auxiliary space.", "Keep the maximum and minimum product ending at the current position.", "Swap them before updating when the next value is negative."],
        ]
    },
    Strings: {
        hints: ["Define character normalization and whether Unicode code points or UTF-16 units are intended.", "Use a frequency map or two pointers, and state how case and punctuation are treated."],
        items: [
            ["Easy", "Reverse a string by Unicode code point", "Implement reverseText(text) that reverses Unicode code points rather than UTF-16 code units, preserving characters such as emoji. Do not reverse grapheme clusters unless you explicitly use an Intl.Segmenter extension.", "'road' => 'daor'; 'A🙂B' => 'B🙂A'.", "An empty string remains empty and does not throw.", "function reverseText(text) { return Array.from(text).reverse().join(''); }", "O(n) time and O(n) space.", "Array.from iterates code points, unlike splitting into UTF-16 code units.", "Reverse the code point array and join it back to a string."],
            ["Easy", "Count vowels without counting uppercase twice", "Write countVowels(text) that counts English a, e, i, o, u case-insensitively and ignores all other characters. Define y as a consonant for this exercise.", "'AI Career OS!' => 6.", "An empty or punctuation-only string returns 0.", "function countVowels(s) { return (s.match(/[aeiou]/gi) || []).length; }", "O(n) time and O(n) space for the regular-expression match result.", "Use a case-insensitive character class limited to the five specified vowels.", "The null match fallback handles inputs with no vowels."],
            ["Easy", "Check whether a phrase is a palindrome", "Implement isPalindrome(text) considering only ASCII letters and digits and ignoring case. Return a boolean without constructing a reversed copy of the full string.", "'A man, a plan, a canal: Panama' => true.", "'0P' => false; punctuation-only input => true.", "function isPalindrome(s) { let l=0,r=s.length-1; const keep=(c)=>/[a-z0-9]/i.test(c); while(l<r){ if(!keep(s[l])){l++;continue;} if(!keep(s[r])){r--;continue;} if(s[l++].toLowerCase()!==s[r--].toLowerCase()) return false; } return true; }", "O(n) time and O(1) extra space.", "Move each pointer past non-alphanumeric characters before comparing.", "A mismatch can return immediately; crossing pointers means all pairs matched."],
            ["Medium", "Group anagrams by character counts", "Implement groupAnagrams(words) for lowercase English words. Group words with the same letter counts, preserve original word order within groups, and keep group ordering by first occurrence.", "['eat','tea','tan','ate'] => [['eat','tea','ate'],['tan']].", "Empty string forms one valid anagram group; empty input returns [].", "function groupAnagrams(words) { const groups=new Map(); for(const word of words){ const count=Array(26).fill(0); for(const ch of word) count[ch.charCodeAt(0)-97]++; const key=count.join('#'); if(!groups.has(key)) groups.set(key,[]); groups.get(key).push(word); } return [...groups.values()]; }", "O(total characters + 26k) time and O(total characters + 26k) space for k groups.", "Use a 26-count signature so words with identical character frequencies share a key.", "Map preserves first-seen key order and appending preserves input order in each group."],
            ["Medium", "Find the longest substring without repeats", "Implement longestUniqueLength(text) returning the longest length of a substring with no repeated Unicode code points. Use a moving window and a map of last-seen positions.", "'abcabcbb' => 3; 'pwwkew' => 3.", "Empty input returns 0; '🙂🙂' returns 1.", "function longestUniqueLength(s) { const chars=Array.from(s), last=new Map(); let left=0,best=0; for(let right=0;right<chars.length;right++){const c=chars[right]; if(last.has(c)) left=Math.max(left,last.get(c)+1); last.set(c,right); best=Math.max(best,right-left+1);} return best; }", "O(n) time and O(min(n, alphabet)) space.", "When a repeated character is inside the window, move left just past its previous occurrence.", "Use Math.max so a repeat before the current window cannot move left backward."],
            ["Medium", "Compress repeated character runs", "Implement runLengthEncode(text) that replaces consecutive equal code points with character plus count only when the result is shorter; otherwise return the original string. Never merge non-adjacent repeats.", "'aaabbc' => 'a3b2c'.", "'abc' remains 'abc'; empty input remains empty.", "function runLengthEncode(s) { const a=Array.from(s); if(!a.length)return s; let out='',count=1; for(let i=1;i<=a.length;i++){if(a[i]===a[i-1])count++;else{out+=a[i-1]+(count>1?count:'');count=1;}} return out.length<s.length?out:s; }", "O(n) time and O(n) output space.", "Scan one run at a time and flush it when the current code point changes.", "Compare output length with original UTF-16 length only if that is the stated encoding contract."],
            ["Hard", "Find the minimum window containing a pattern", "Implement minWindow(source,target) returning the shortest substring containing every target character with multiplicity. Return empty string when no window exists; use a sliding window and frequency counts.", "source='ADOBECODEBANC', target='ABC' => 'BANC'.", "An empty target or impossible target returns ''.", "function minWindow(s,t) { if(!t.length||t.length>s.length)return ''; const need=new Map(); for(const c of t)need.set(c,(need.get(c)||0)+1); let missing=t.length,left=0,best=[0,Infinity]; for(let right=0;right<s.length;right++){const c=s[right]; if(need.has(c)){if(need.get(c)>0)missing--;need.set(c,need.get(c)-1);} while(missing===0){if(right-left<best[1]-best[0])best=[left,right+1]; const x=s[left++]; if(need.has(x)){need.set(x,need.get(x)+1);if(need.get(x)>0)missing++;}}} return best[1]===Infinity?'':s.slice(...best); }", "O(n+m) time and O(m) space for source length n and target length m.", "Track how many target characters remain missing, including repeated occurrences.", "Shrink from the left while all requirements are met, recording the smallest valid interval."],
            ["Hard", "Decode nested repeat notation", "Implement decodeString(input) for grammar k[encoded], where k is a non-negative integer and brackets may nest. Reject unmatched brackets or digits not followed by an opening bracket; impose a maximum output length to prevent resource exhaustion.", "'3[a2[c]]' => 'accaccacc'.", "'0[abc]' => ''; malformed '2[a' throws; excessive expansion is rejected.", "function decodeString(s,max=100000) { const counts=[],parts=[]; let cur='',num=0,readingNumber=false; for(const ch of s){ if(/\\d/.test(ch)){readingNumber=true;num=num*10+Number(ch);if(!Number.isSafeInteger(num))throw Error('Invalid repeat');} else if(ch==='['){if(!readingNumber)throw Error('Missing repeat');counts.push(num);parts.push(cur);cur='';num=0;readingNumber=false;} else if(ch===']'){if(!counts.length||readingNumber)throw Error('Malformed');const k=counts.pop();cur=parts.pop()+cur.repeat(k);if(cur.length>max)throw Error('Output too large');} else {if(readingNumber)throw Error('Malformed');cur+=ch;} } if(counts.length||readingNumber)throw Error('Malformed'); return cur; }", "O(output length) time and space, bounded here by max output length.", "Push the previous string and repeat count when entering a bracket, then combine on close.", "Track a separate digit-state so a repeat count of zero is not confused with no count."],
            ["Hard", "Find the longest palindromic substring", "Implement longestPalindrome(text) using expand-around-center. Return one longest substring; if several tie, return the leftmost. Operate on UTF-16 code units as JavaScript slice does, and state this limitation.", "'babad' => 'bab' under the leftmost tie rule.", "Empty input returns ''; 'cbbd' => 'bb'.", "function longestPalindrome(s) { let start=0,end=0; const expand=(l,r)=>{while(l>=0&&r<s.length&&s[l]===s[r]){l--;r++;}return [l+1,r-1];}; for(let i=0;i<s.length;i++){for(const [l,r] of [expand(i,i),expand(i,i+1)]) if(r-l>end-start){start=l;end=r;}} return s.slice(start,end+1); }", "O(n²) time and O(1) extra space.", "Every palindrome has an odd or even center; expand until characters differ.", "Update only for a strictly longer range so equal-length ties keep the earlier substring."],
        ]
    },
    "Hash Maps": {
        hints: ["Choose a key that represents the exact equality rule in the problem.", "Check collisions, missing keys, repeated inputs, and whether iteration order is part of the contract."],
        items: [
            ["Easy", "Count word frequencies", "Implement wordCounts(text) that splits on whitespace, trims punctuation from word boundaries, lowercases words, and returns a Map of frequencies. Ignore tokens that become empty.", "'Go, go! Learn JS' => go:2, learn:1, js:1.", "Whitespace-only input returns an empty Map.", "function wordCounts(text) { const map=new Map(); for(const raw of text.split(/\\s+/)){const word=raw.replace(/^[^a-z0-9]+|[^a-z0-9]+$/gi,'').toLowerCase();if(word)map.set(word,(map.get(word)||0)+1);} return map; }", "O(n) time in text length and O(u) space for u distinct words.", "Normalize each token before using it as a Map key.", "Increment the stored count or initialize it to one; skip empty normalized tokens."],
            ["Easy", "Find the first repeated value", "Implement firstRepeat(values) returning the earliest value whose second occurrence appears first during a left-to-right scan. Use a Set; return null if every value is unique.", "[4,2,5,2,4] => 2.", "[] and all-unique input return null.", "function firstRepeat(a) { const seen=new Set(); for(const value of a){if(seen.has(value))return value;seen.add(value);} return null; }", "O(n) expected time and O(n) space.", "A Set records values already encountered while scanning in order.", "Return on the first duplicate encountered, not the value with the earliest first position."],
            ["Easy", "Compare two strings as multisets", "Implement sameCharacters(a,b) that returns true when both strings contain the same characters with the same multiplicities, ignoring order but remaining case-sensitive.", "'listen' and 'silent' => true.", "'aab' and 'abb' => false; two empty strings => true.", "function sameCharacters(a,b) { if(a.length!==b.length)return false; const counts=new Map(); for(const c of a)counts.set(c,(counts.get(c)||0)+1); for(const c of b){const n=counts.get(c);if(!n)return false;if(n===1)counts.delete(c);else counts.set(c,n-1);} return counts.size===0; }", "O(n) expected time and O(u) space.", "Count the first string, then decrement counts for the second.", "A missing or exhausted count proves the multisets differ."],
            ["Medium", "Return indices for two-sum", "Implement twoSum(values,target) returning the first pair of distinct indices whose values add to target, scanning rightward and using a Map from value to earliest index. Return null if no pair exists.", "[2,7,11,15], target 9 => [0,1].", "[3,3], target 6 => [0,1]; no solution returns null.", "function twoSum(a,target) { const first=new Map(); for(let i=0;i<a.length;i++){const other=target-a[i];if(first.has(other))return [first.get(other),i];if(!first.has(a[i]))first.set(a[i],i);} return null; }", "O(n) expected time and O(n) space.", "At each index, look up the needed complement before recording the current value.", "This ordering prevents using the same element twice and preserves the earliest seen index."],
            ["Medium", "Group records by normalized email", "Implement groupByEmail(users) using lowercase trimmed email as the key. Skip missing emails, preserve input order within each group, and return a Map so arbitrary strings remain safe keys.", "Users with ' A@EXAMPLE.test ' and 'a@example.test' share one group.", "A user with no usable email is excluded rather than grouped under an empty key.", "function groupByEmail(users) { const groups=new Map(); for(const user of users){const key=typeof user.email==='string'?user.email.trim().toLowerCase():'';if(!key)continue;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(user);}return groups; }", "O(n) expected time plus email normalization cost and O(n) grouping space.", "Normalize once per record and use the normalized value consistently.", "Map avoids prototype-key hazards and append order remains stable."],
            ["Medium", "Find the longest consecutive integer run", "Implement longestConsecutive(nums) in expected O(n) time using a Set. Return the length of the longest consecutive-value sequence regardless of input order; duplicates do not extend a run.", "[100,4,200,1,3,2] => 4.", "[] => 0; duplicates in [1,1,2] yield 2.", "function longestConsecutive(a) { const set=new Set(a);let best=0;for(const n of set){if(!set.has(n-1)){let x=n;while(set.has(x+1))x++;best=Math.max(best,x-n+1);}}return best; }", "O(n) expected time and O(n) space.", "Start a scan only at values that have no predecessor in the set.", "Each consecutive run is expanded once from its smallest value."],
            ["Hard", "Build an LRU cache with O(1) operations", "Implement an LRU cache with get and set in expected O(1) time and a positive capacity. Use a Map's insertion order to represent recency; get promotes a key and set evicts the least recently used key when full.", "Capacity 2: set a,b; get a; set c evicts b.", "Capacity 1 evicts the old key; reading a missing key returns -1.", "class LRUCache { constructor(capacity){if(!Number.isInteger(capacity)||capacity<1)throw RangeError();this.capacity=capacity;this.map=new Map();} get(key){if(!this.map.has(key))return -1;const value=this.map.get(key);this.map.delete(key);this.map.set(key,value);return value;} set(key,value){if(this.map.has(key))this.map.delete(key);this.map.set(key,value);if(this.map.size>this.capacity)this.map.delete(this.map.keys().next().value);} }", "O(1) expected time per operation and O(capacity) space.", "Map iteration order is oldest to newest; delete/reinsert promotes a key.", "After inserting, evict the first Map key only when size exceeds capacity."],
            ["Hard", "Count subarrays with sum k", "Implement subarraySumCount(values,k) returning the number of contiguous subarrays summing to k. Use prefix sums and a frequency Map so negative values are handled correctly.", "[1,1,1], k=2 => 2; [1,-1,0], k=0 => 3.", "An empty input returns 0; all-zero arrays count every valid subarray.", "function subarraySumCount(a,k) { const freq=new Map([[0,1]]);let sum=0,count=0;for(const x of a){sum+=x;count+=freq.get(sum-k)||0;freq.set(sum,(freq.get(sum)||0)+1);}return count; }", "O(n) expected time and O(n) space.", "For each prefix sum, prior prefix sums equal to current-k define matching subarrays.", "Seed frequency zero with one to count ranges starting at index zero."],
            ["Hard", "Find a minimum covering window of integers", "Given source and required integer arrays, implement minimumCoveringRange that returns the shortest inclusive source index range containing every required value with multiplicity. Return null when impossible and break ties by earliest start index.", "source=[1,2,1,3,2], required=[1,2,2] => [1,4].", "Empty required input returns [0,-1]; impossible multiplicities return null.", "function minimumCoveringRange(source,required) { if(!required.length)return [0,-1];const need=new Map();for(const x of required)need.set(x,(need.get(x)||0)+1);let missing=required.length,left=0,best=null;for(let right=0;right<source.length;right++){const x=source[right];if(need.has(x)){if(need.get(x)>0)missing--;need.set(x,need.get(x)-1);}while(!missing){if(!best||right-left<best[1]-best[0])best=[left,right];const y=source[left++];if(need.has(y)){need.set(y,need.get(y)+1);if(need.get(y)>0)missing++;}}}return best; }", "O(n+m) expected time and O(u) space for unique values in required.", "Track required multiplicities and shrink the window only while all are covered.", "Update only for a strictly shorter range so equal-size ties preserve earliest start."],
        ]
    },
    "Linked Lists": {
        hints: ["Draw node references before changing next pointers; save the successor before relinking.", "Check null head, one node, cycles, and exact removal semantics."],
        items: [
            ["Easy", "Count nodes in a singly linked list", "Implement listLength(head) for nodes shaped {value,next}. Traverse until null and return the node count without modifying links.", "1 → 2 → 3 → null returns 3.", "null returns 0; one node returns 1.", "function listLength(head) { let count=0;for(let node=head;node;node=node.next)count++;return count; }", "O(n) time and O(1) space.", "Advance through next pointers and count each visited node once.", "A null head naturally returns zero without a special dereference."],
            ["Easy", "Find a value in a linked list", "Implement findNode(head,target) returning the first node whose value strictly equals target, or null. Do not change the list while searching.", "1 → 4 → 7, target 4 returns the second node.", "An empty list or absent value returns null.", "function findNode(head,target) { for(let node=head;node;node=node.next)if(node.value===target)return node;return null; }", "O(n) time and O(1) space.", "Check each node before following its next reference.", "Return the first strict match to preserve list order semantics."],
            ["Easy", "Append a node to a list", "Implement appendNode(head,value) that returns the head of a list with a new node appended. Do not mutate the existing list; return a copied chain and preserve values in order.", "[1,2] plus 3 returns [1,2,3].", "Appending to null creates a single-node list.", "function appendNode(head,value) { const dummy={next:null};let tail=dummy;for(let n=head;n;n=n.next){tail.next={value:n.value,next:null};tail=tail.next;}tail.next={value,next:null};return dummy.next; }", "O(n) time and O(n) new nodes.", "Use a dummy head and copy each existing value before attaching the new node.", "The dummy node avoids a separate empty-list branch for linking."],
            ["Medium", "Reverse a singly linked list", "Implement reverseList(head) in place using constant extra space. Return the new head and ensure no nodes are lost when next references are reversed.", "1 → 2 → 3 becomes 3 → 2 → 1.", "null remains null; one node remains the same node.", "function reverseList(head) { let prev=null,curr=head;while(curr){const next=curr.next;curr.next=prev;prev=curr;curr=next;}return prev; }", "O(n) time and O(1) space.", "Save curr.next before redirecting the link backward.", "Move prev and curr forward using the saved successor until curr is null."],
            ["Medium", "Remove the nth node from the end", "Implement removeNthFromEnd(head,n) using one pass and a dummy node. Remove exactly the nth node from the end; reject n < 1 or n greater than list length.", "1 → 2 → 3 → 4, n=2 becomes 1 → 2 → 4.", "n equal to list length removes the head; invalid n throws without mutation.", "function removeNthFromEnd(head,n) { if(!Number.isInteger(n)||n<1)throw RangeError();const dummy={next:head};let fast=dummy,slow=dummy;for(let i=0;i<n;i++){fast=fast.next;if(!fast)throw RangeError();}while(fast.next){fast=fast.next;slow=slow.next;}slow.next=slow.next.next;return dummy.next; }", "O(n) time and O(1) space.", "Advance fast n steps, then move both pointers until fast reaches the tail.", "slow stops immediately before the node to unlink; the dummy supports removing the head."],
            ["Medium", "Merge two sorted linked lists", "Implement mergeLists(a,b) by relinking existing nodes into one ascending list. Reuse nodes, preserve every value, and do not create an array or sort after traversal.", "1→3→5 and 2→4 => 1→2→3→4→5.", "Either list may be null; equal values from both lists are preserved.", "function mergeLists(a,b) { const dummy={next:null};let tail=dummy;while(a&&b){if(a.value<=b.value){tail.next=a;a=a.next;}else{tail.next=b;b=b.next;}tail=tail.next;}tail.next=a||b;return dummy.next; }", "O(n+m) time and O(1) extra space.", "Repeatedly link the smaller head and advance that input list.", "Attach the remaining suffix after one list is exhausted."],
            ["Hard", "Detect a cycle and return its entry", "Implement cycleEntry(head) using Floyd's tortoise-and-hare algorithm. Return the node where a cycle begins or null when the list is acyclic, without modifying links.", "A list whose tail points to node 2 returns that node.", "null and a self-loop are handled correctly.", "function cycleEntry(head) { let slow=head,fast=head;do{if(!fast||!fast.next)return null;slow=slow.next;fast=fast.next.next;}while(slow!==fast);slow=head;while(slow!==fast){slow=slow.next;fast=fast.next;}return slow; }", "O(n) time and O(1) space.", "First find a meeting point with slow and fast pointers.", "Reset one pointer to head; advancing both one step meets at the cycle entry."],
            ["Hard", "Reorder a list first-last-first", "Implement reorderList(head) in place to transform L0→L1→…→Ln into L0→Ln→L1→Ln-1. Use O(1) extra space and do not allocate replacement nodes.", "1→2→3→4→5 becomes 1→5→2→4→3.", "A two-node list is unchanged; an even list uses the same alternating pattern.", "function reorderList(head) { if(!head||!head.next)return head;let slow=head,fast=head;while(fast.next&&fast.next.next){slow=slow.next;fast=fast.next.next;}let second=slow.next;slow.next=null;let prev=null;while(second){const next=second.next;second.next=prev;prev=second;second=next;}let first=head;second=prev;while(second){const n1=first.next,n2=second.next;first.next=second;second.next=n1;first=n1;second=n2;}return head; }", "O(n) time and O(1) space.", "Split at the middle, reverse the second half, then weave nodes alternately.", "Cut the first half before reversing to avoid retaining a cycle during the merge."],
            ["Hard", "Copy a list with random pointers", "Each node has next and random references. Implement copyRandomList(head) returning a deep copy with every random pointer targeting the corresponding copied node, using a Map and without changing the original list.", "Copied nodes have same values and corresponding random relationships.", "null returns null; random may be null or point to any list node.", "function copyRandomList(head) { const copies=new Map([[null,null]]);for(let n=head;n;n=n.next)copies.set(n,{value:n.value,next:null,random:null});for(let n=head;n;n=n.next){const c=copies.get(n);c.next=copies.get(n.next);c.random=copies.get(n.random);}return copies.get(head); }", "O(n) time and O(n) space.", "Create a copied node for every original before wiring any references.", "A second pass maps each original next/random target to its copied counterpart."],
        ]
    },
    Stacks: {
        hints: ["A stack is last-in, first-out; identify exactly what each push/pop represents.", "Guard empty operations and keep each delimiter or nested value paired with its opener."],
        items: [
            ["Easy", "Validate balanced parentheses", "Implement balanced(text) for only parentheses characters '(' and ')'. Return true when every opener is closed in the correct order; reject a close with no opener.", "'(())()' => true.", "'())(' and '(()' => false; empty string => true.", "function balanced(s) { let depth=0;for(const c of s){if(c==='(')depth++;else if(c===')'){depth--;if(depth<0)return false;}else throw TypeError('Unexpected character');}return depth===0; }", "O(n) time and O(1) space for one bracket type.", "Track unmatched open parentheses as a depth counter.", "Never let depth become negative, and require zero at the end."],
            ["Easy", "Implement a stack with constant-time top", "Create a Stack class supporting push, pop, peek, and size using an array. Empty pop and peek return undefined; operations must not expose the internal array.", "push(3), push(5), peek() => 5; pop() => 5.", "Popping an empty stack leaves size at zero.", "class Stack { constructor(){this.items=[];} push(value){this.items.push(value);} pop(){return this.items.pop();} peek(){return this.items.at(-1);} get size(){return this.items.length;} }", "O(1) amortized per operation and O(n) storage.", "Use the array end consistently as the top of the stack.", "Array push/pop/at(-1) avoid shifting every item."],
            ["Easy", "Reverse words with stack order", "Implement reverseWords(text) that splits on whitespace, removes empty tokens, reverses word order with a stack, and joins with one space. Preserve each word's character casing.", "'learn   data structures' => 'structures data learn'.", "Whitespace-only input returns ''.", "function reverseWords(s) { const stack=s.trim().split(/\\s+/).filter(Boolean);const out=[];while(stack.length)out.push(stack.pop());return out.join(' '); }", "O(n) time and O(n) space.", "Normalize token boundaries, then pop the words in last-in-first-out order.", "Filter empty tokens before pushing so repeated whitespace adds no blank word."],
            ["Medium", "Evaluate a postfix expression", "Implement evaluatePostfix(tokens) for integer operands and +, -, *, /. Division truncates toward zero. Reject insufficient operands, unknown tokens, division by zero, and a final stack size other than one.", "['2','1','+','3','*'] => 9.", "['4','0','/'] throws; a single number returns itself.", "function evaluatePostfix(tokens) { const s=[];for(const t of tokens){if(/^-?\\d+$/.test(t)){s.push(Number(t));continue;}if(!['+','-','*','/'].includes(t)||s.length<2)throw Error('Invalid expression');const b=s.pop(),a=s.pop();if(t==='/'&&b===0)throw RangeError('Division by zero');s.push(t==='+'?a+b:t==='-'?a-b:t==='*'?a*b:Math.trunc(a/b));}if(s.length!==1)throw Error('Invalid expression');return s[0]; }", "O(n) time and O(n) stack space.", "Push operands; for an operator, pop right then left and push the result.", "Validate arity and division before applying each operation, then require exactly one result."],
            ["Medium", "Find the next warmer day", "For each daily temperature, return how many days until a warmer temperature, or zero if none. Use a monotonic stack of unresolved indices and return an array of equal length.", "[73,74,75,71,69,72,76,73] => [1,1,4,2,1,1,0,0].", "Empty input returns []; equal temperatures do not count as warmer.", "function dailyTemperatures(t) { const out=Array(t.length).fill(0),stack=[];for(let i=0;i<t.length;i++){while(stack.length&&t[i]>t[stack.at(-1)]){const j=stack.pop();out[j]=i-j;}stack.push(i);}return out; }", "O(n) time and O(n) space; each index enters and leaves the stack once.", "Keep indices whose warmer day has not yet appeared.", "Resolve the top while the current temperature is strictly higher."],
            ["Medium", "Simplify a Unix path", "Implement simplifyPath(path) for absolute Unix paths, handling repeated slashes, '.', and '..'. Parent navigation at root stays at root; return a canonical absolute path.", "'/a/./b/../../c/' => '/c'.", "'////' => '/'; '/../../x' => '/x'.", "function simplifyPath(path) { const stack=[];for(const part of path.split('/')){if(!part||part==='.')continue;if(part==='..')stack.pop();else stack.push(part);}return '/'+stack.join('/'); }", "O(n) time and O(n) space in path length.", "Push normal segments, ignore '.', and pop for '..'.", "An empty stack naturally prevents traversal above root."],
            ["Hard", "Find the largest rectangle in a histogram", "Implement largestRectangle(heights) using a monotonic increasing index stack and a sentinel at the end. Heights are non-negative integers; return maximum rectangle area.", "[2,1,5,6,2,3] => 10.", "[] and all-zero heights return 0.", "function largestRectangle(h) { const stack=[];let best=0;for(let i=0;i<=h.length;i++){const current=i===h.length?0:h[i];while(stack.length&&h[stack.at(-1)]>current){const height=h[stack.pop()];const left=stack.length?stack.at(-1):-1;best=Math.max(best,height*(i-left-1));}stack.push(i);}return best; }", "O(n) time and O(n) space; each index is pushed and popped once.", "When a lower bar arrives, it fixes the right boundary of taller bars on the stack.", "After popping, the new stack top determines the previous smaller boundary."],
            ["Hard", "Support a stack with constant-time minimum", "Design MinStack with push, pop, top, and getMin in O(1) time. Duplicated minimum values must remain correct after one copy is popped.", "Push 5,2,2; pop once; getMin() remains 2.", "Empty getMin returns undefined or throws according to a documented consistent contract.", "class MinStack { constructor(){this.values=[];this.mins=[];} push(x){this.values.push(x);if(!this.mins.length||x<=this.mins.at(-1))this.mins.push(x);} pop(){const x=this.values.pop();if(x===this.mins.at(-1))this.mins.pop();return x;} top(){return this.values.at(-1);} getMin(){return this.mins.at(-1);} }", "O(1) time per operation and O(n) extra space in the worst case.", "Keep a second stack of minima, pushing equal minima as well as smaller ones.", "Pop the minimum stack only when the removed value equals its top."],
            ["Hard", "Compute a maximum over every sliding window", "Implement maxSlidingWindow(values,k) using a deque of indices in decreasing value order. Return the maximum for each full window in O(n) time.", "[1,3,-1,-3,5,3,6,7], k=3 => [3,3,5,5,6,7].", "k=1 returns a copy; k outside 1..n is rejected.", "function maxSlidingWindow(a,k) { if(!Number.isInteger(k)||k<1||k>a.length)throw RangeError();const q=[],out=[];for(let i=0;i<a.length;i++){while(q.length&&q[0]<=i-k)q.shift();while(q.length&&a[q.at(-1)]<=a[i])q.pop();q.push(i);if(i>=k-1)out.push(a[q[0]]);}return out; }", "O(n) amortized time and O(k) space; use a deque with O(1) front removal in production.", "Discard expired indices from the front and dominated values from the back.", "Each index enters and leaves the deque at most once."],
        ]
    },
    Queues: {
        hints: ["A queue is first-in, first-out; avoid array shift in performance-sensitive loops.", "For circular buffers, track head, tail, and size explicitly to distinguish full from empty."],
        items: [
            ["Easy", "Simulate a print queue", "Implement processNext(queue) that returns the next print job and a new queue without mutating the original. Empty input returns {job:null,queue:[]}.", "['resume.pdf','report.pdf'] returns resume.pdf and ['report.pdf'].", "An empty queue stays empty and has no job.", "function processNext(queue) { return queue.length ? { job: queue[0], queue: queue.slice(1) } : { job: null, queue: [] }; }", "O(n) time and O(n) output space for an immutable array slice.", "The first array element is the oldest queued job.", "Return the suffix as the next queue and keep the source intact."],
            ["Easy", "Generate a binary number sequence", "Use a queue to generate the first n positive binary numbers in order, starting with '1'. Each dequeued string produces children formed by appending '0' and '1'.", "n=5 => ['1','10','11','100','101'].", "n=0 returns []; negative n is rejected.", "function binarySequence(n) { if(!Number.isInteger(n)||n<0)throw RangeError();const q=['1'],out=[];for(let head=0;head<n;head++){const x=q[head];out.push(x);q.push(x+'0',x+'1');}return out; }", "O(total output characters) time and O(total generated prefix strings) space.", "Process the front in FIFO order and enqueue its two children; a head index avoids shifting the remaining queue.", "The queue order yields binary strings in increasing numeric order."],
            ["Easy", "Interleave two halves of a queue", "Given an even-length queue, interleave its first half with its second half while preserving order. Reject odd lengths rather than silently dropping an item.", "[1,2,3,4,5,6] => [1,4,2,5,3,6].", "[] returns []; odd input throws RangeError.", "function interleaveHalves(q) { if(q.length%2)throw RangeError('Even length required');const half=q.length/2,out=[];for(let i=0;i<half;i++)out.push(q[i],q[i+half]);return out; }", "O(n) time and O(n) output space.", "Pair item i from the first half with item i from the second half.", "Validate even length before computing half boundaries."],
            ["Medium", "Implement a circular queue", "Build a fixed-capacity circular queue with enqueue, dequeue, front, isEmpty, and isFull. Use head and size so capacity slots are all usable and wraparound does not shift elements.", "Capacity 3: enqueue a,b; dequeue; enqueue c,d; front() is b.", "Capacity must be positive; full enqueue and empty dequeue return false/undefined consistently.", "class CircularQueue { constructor(k){if(!Number.isInteger(k)||k<1)throw RangeError();this.a=Array(k);this.head=0;this.size=0;} enqueue(x){if(this.size===this.a.length)return false;this.a[(this.head+this.size)%this.a.length]=x;this.size++;return true;} dequeue(){if(!this.size)return undefined;const x=this.a[this.head];this.head=(this.head+1)%this.a.length;this.size--;return x;} front(){return this.size?this.a[this.head]:undefined;} isEmpty(){return this.size===0;} isFull(){return this.size===this.a.length;} }", "O(1) time per operation and O(capacity) space.", "Compute insertion index as (head+size) mod capacity.", "Advance head modulo capacity and maintain size to distinguish full from empty."],
            ["Medium", "Process tasks in round-robin order", "Simulate a round-robin scheduler where each task has remaining time and receives quantum q. Re-enqueue unfinished tasks; record completion order and total elapsed time for each task.", "Tasks A:3, B:1 with q=2 complete B then A at total times 3 and 4.", "An empty task list returns []; q must be a positive integer and task durations must be positive.", "function roundRobin(tasks,q) { if(!Number.isInteger(q)||q<1||tasks.some(t=>t.remaining<=0))throw RangeError();const queue=tasks.map(t=>({...t})),done=[];let time=0;for(let head=0;head<queue.length;head++){const t=queue[head],run=Math.min(q,t.remaining);time+=run;t.remaining-=run;if(t.remaining===0)done.push({id:t.id,finishedAt:time});else queue.push(t);}return done; }", "O(total number of quanta) time and O(number of tasks plus requeued turns) storage.", "Run the front task for min(quantum, remaining) and append unfinished work at the tail using a head index.", "Elapsed time advances only by actual run duration."],
            ["Medium", "Find the first non-repeating stream character", "For a stream of lowercase characters, after each new character report the first character seen exactly once so far, or '#'. Use a queue plus frequency counts.", "'aabc' => ['a','#','b','b'].", "Empty stream emits no outputs; repeated characters are removed from consideration at the queue front.", "function firstUniqueStream(s) { const count=new Map(),q=[],out=[];let head=0;for(const c of s){count.set(c,(count.get(c)||0)+1);if(count.get(c)===1)q.push(c);while(head<q.length&&count.get(q[head])>1)head++;out.push(q[head]||'#');}return out; }", "O(n) amortized time and O(u) space.", "Enqueue a character when first seen and advance a head index past repeated values.", "A character that becomes repeated can never become unique again."],
            ["Hard", "Find shortest path in an unweighted grid", "Given a grid with 0 open and 1 blocked cells, implement shortestSteps from top-left to bottom-right with four-direction movement using BFS. Return -1 if unreachable and mark visited when enqueued.", "[[0,0],[1,0]] => 2.", "Blocked start/end or empty grid returns -1; a one-cell open grid returns 0.", "function shortestSteps(grid) { const m=grid.length,n=grid[0]?.length||0;if(!m||!n||grid[0][0]||grid[m-1][n-1])return -1;const q=[[0,0,0]],seen=new Set(['0,0']);for(let head=0;head<q.length;head++){const [r,c,d]=q[head];if(r===m-1&&c===n-1)return d;for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]){const nr=r+dr,nc=c+dc,key=`${nr},${nc}`;if(nr>=0&&nr<m&&nc>=0&&nc<n&&!grid[nr][nc]&&!seen.has(key)){seen.add(key);q.push([nr,nc,d+1]);}}}return -1; }", "O(rows×columns) time and space.", "BFS explores positions in increasing distance from the start.", "Mark visited at enqueue time so a cell cannot be added repeatedly."],
            ["Hard", "Design a bounded work queue", "Implement a FIFO work queue with a fixed capacity, enqueue rejection when full, dequeue, and a close operation. After close, reject new work but allow already queued work to drain before reporting closed-and-empty.", "Capacity 2 accepts two tasks, rejects a third, and drains the first two in order.", "Capacity must be a positive integer; closing an empty queue makes dequeue report closed; closing twice is safe.", "class WorkQueue { constructor(capacity){if(!Number.isInteger(capacity)||capacity<1)throw RangeError();this.capacity=capacity;this.items=Array(capacity);this.head=0;this.size=0;this.closed=false;} enqueue(x){if(this.closed||this.size===this.capacity)return false;this.items[(this.head+this.size)%this.capacity]=x;this.size++;return true;} close(){this.closed=true;} dequeue(){if(!this.size)return {status:this.closed?'closed':'empty'};const value=this.items[this.head];this.items[this.head]=undefined;this.head=(this.head+1)%this.capacity;this.size--;return {status:'item',value};} }", "O(1) enqueue/dequeue time and O(capacity) storage.", "Track head and size separately; an empty queue and a closed-empty queue have distinct states.", "Do not discard queued items on close; reject only future enqueues."],
            ["Hard", "Compute moving averages with a queue", "For a numeric stream and window size k, output each full-window average using a queue and rolling sum rather than summing each window from scratch.", "[1,2,3,4], k=2 => [1.5,2.5,3.5].", "k=1 returns each value; k larger than input length returns [].", "function movingAverage(a,k) { if(!Number.isInteger(k)||k<1)throw RangeError();const ring=Array(k),out=[];let sum=0,count=0,head=0;for(const x of a){if(count===k){sum-=ring[head];ring[head]=x;head=(head+1)%k;}else{ring[(head+count)%k]=x;count++;}sum+=x;if(count===k)out.push(sum/k);}return out; }", "O(n) time and O(k) window space.", "Store exactly k recent values in a ring and maintain the sum as values enter and leave.", "The head index always identifies the oldest value in a full window."],
        ]
    },
    Recursion: {
        hints: ["Define a base case that reduces the remaining problem and returns the correct identity value.", "Trace call depth and repeated subproblems; use memoization or iteration when depth/work can grow large."],
        items: [
            ["Easy", "Compute a factorial with a base case", "Implement factorial(n) recursively for non-negative integers. Define 0! as 1, reject invalid input, and explain why every recursive call moves toward the base case.", "factorial(5) => 120.", "factorial(0) => 1; negative and non-integer values are rejected.", "function factorial(n) { if(!Number.isInteger(n)||n<0)throw RangeError();if(n===0)return 1;return n*factorial(n-1); }", "O(n) time and O(n) call-stack space.", "Use 0! = 1 as the base case and reduce n by one per call.", "The recursive product unwinds after factorial(0) returns."],
            ["Easy", "Sum a nested array of integers", "Implement recursiveSum(values) for a flat array of finite numbers using recursion rather than reduce. The empty-array base case returns zero and the input is not modified.", "[2,-1,5] => 6.", "[] => 0; non-number values are rejected.", "function recursiveSum(a,index=0) { if(index===a.length)return 0;if(!Number.isFinite(a[index]))throw TypeError();return a[index]+recursiveSum(a,index+1); }", "O(n) time and O(n) stack space.", "The base case is the index at array length, with zero as the sum identity.", "Each call consumes exactly one array value and adds it during unwind."],
            ["Easy", "Generate a string recursively", "Implement repeatText(text,count) recursively, returning text repeated count times. Require a non-negative integer count and return an empty string at zero.", "repeatText('ha',3) => 'hahaha'.", "count 0 returns ''; invalid or overly large counts above 10000 are rejected.", "function repeatText(text,count) { if(!Number.isInteger(count)||count<0||count>10000)throw RangeError();if(count===0)return '';return text+repeatText(text,count-1); }", "O(n×text length) time and O(n) stack space for count n.", "Use count zero as the terminating case.", "Reduce count by one and concatenate exactly one copy per frame."],
            ["Medium", "Flatten a nested integer list", "Implement flattenNested(value) recursively for arrays nested to arbitrary reasonable depth, preserving left-to-right order and rejecting non-number leaves. Return a new flat array.", "[1,[2,[3]],4] => [1,2,3,4].", "[] and nested empty arrays return []; a string leaf is rejected.", "function flattenNested(value) { if(!Array.isArray(value)){if(!Number.isFinite(value))throw TypeError();return [value];}const out=[];for(const item of value)out.push(...flattenNested(item));return out; }", "O(n) time/output space for n leaves; O(depth) call stack.", "Treat an array as a sequence of smaller flattening problems.", "Append each child's flattened values in original order."],
            ["Medium", "Generate all subsets recursively", "Implement subsets(values) returning the power set of distinct input values in the order where each value's exclude branch precedes its include branch. The input array is not mutated.", "[1,2] => [[],[2],[1],[1,2]].", "Empty input returns [[]].", "function subsets(a,index=0,current=[],out=[]) { if(index===a.length){out.push([...current]);return out;}subsets(a,index+1,current,out);current.push(a[index]);subsets(a,index+1,current,out);current.pop();return out; }", "O(n·2^n) time to materialize subsets and O(n) recursion depth beyond output.", "At each index make two choices: exclude or include the value.", "Push before the include call and pop afterward to backtrack shared path state."],
            ["Medium", "Search a recursive file tree", "A directory is represented by {name,files,children}. Implement findFile(root,target) recursively and return the first matching full path using child order; avoid revisiting a directory ID already seen so cycles cannot recurse forever.", "A file in child folder docs returns '/root/docs/readme.md'.", "A cycle in child references terminates and a missing name returns null.", "function findFile(root,target,seen=new Set(),path='') { if(!root||seen.has(root.id))return null;seen.add(root.id);const here=`${path}/${root.name}`;if(root.files?.includes(target))return `${here}/${target}`;for(const child of root.children||[]){const found=findFile(child,target,seen,here);if(found)return found;}return null; }", "O(V+E) time in the reachable tree/graph and O(V) visited space plus recursion depth.", "Carry the current path and visited IDs through recursive calls.", "Return immediately on the first match; a visited set prevents a cycle from repeating work."],
            ["Hard", "Solve a constrained maze with backtracking", "Given a grid of open and blocked cells, implement allPaths(start,end) returning simple paths using four-direction moves. Use backtracking so cells are unmarked after exploring each branch; return paths as coordinate arrays.", "A 2×2 all-open grid has two simple paths from top-left to bottom-right.", "Blocked or unreachable endpoints return []; a one-cell open grid returns one path containing that cell.", "function allPaths(grid) { const m=grid.length,n=grid[0]?.length||0,out=[],path=[],seen=new Set();if(!m||!n||grid[0][0]||grid[m-1][n-1])return out;function dfs(r,c){const key=`${r},${c}`;if(r<0||r>=m||c<0||c>=n||grid[r][c]||seen.has(key))return;seen.add(key);path.push([r,c]);if(r===m-1&&c===n-1)out.push(path.map((p)=>[...p]));else for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]])dfs(r+dr,c+dc);path.pop();seen.delete(key);}dfs(0,0);return out; }", "Exponential in the number of simple paths in the worst case; O(path length) auxiliary state per depth, excluding results.", "Mark a cell before exploring neighbors and unmark it during backtracking.", "Copy the current path when a solution is found because the working path will continue changing."],
            ["Hard", "Memoize a recursive edit distance", "Implement editDistance(a,b) with recursion and memoization, where insertion, deletion, and substitution each cost one. Return the minimum operations to transform a into b.", "'horse' to 'ros' => 3.", "One empty string returns the other's length; equal strings return 0.", "function editDistance(a,b) { const memo=new Map();function dp(i,j){const key=`${i},${j}`;if(memo.has(key))return memo.get(key);let result;if(i===a.length)result=b.length-j;else if(j===b.length)result=a.length-i;else if(a[i]===b[j])result=dp(i+1,j+1);else result=1+Math.min(dp(i+1,j),dp(i,j+1),dp(i+1,j+1));memo.set(key,result);return result;}return dp(0,0); }", "O(mn) time and O(mn) memo space for string lengths m and n; O(m+n) call depth.", "Define the state by the two current string indices.", "Memoize each state and use the three edit operations only when characters differ."],
            ["Hard", "Generate valid parentheses", "Implement generateParentheses(n) using recursive backtracking to generate all well-formed strings with n pairs. Add '(' only when fewer than n are used and ')' only when it cannot exceed open count.", "n=3 returns five strings, including '((()))' and '()()()'.", "n=0 returns ['']; negative or non-integer n is rejected.", "function generateParentheses(n) { if(!Number.isInteger(n)||n<0)throw RangeError();const out=[];function build(s,open,close){if(s.length===2*n){out.push(s);return;}if(open<n)build(s+'(',open+1,close);if(close<open)build(s+')',open,close+1);}build('',0,0);return out; }", "Catalan output count Cn and O(n) auxiliary recursion/path space beyond output.", "Maintain the invariant close <= open <= n at every partial string.", "Only add a closing parenthesis when it keeps the prefix valid."],
        ]
    },
    Trees: {
        hints: ["Choose preorder, inorder, or postorder based on when a node's value is consumed.", "State whether the structure is a binary tree or BST; do not apply ordering assumptions to arbitrary trees."],
        items: [
            ["Easy", "Count nodes in a binary tree", "Implement countNodes(root) recursively for a binary tree node with left and right children. Return zero for an empty subtree.", "A root with two children returns 3.", "null returns 0; a single node returns 1.", "function countNodes(node) { return node ? 1+countNodes(node.left)+countNodes(node.right) : 0; }", "O(n) time and O(h) recursion stack for height h.", "Count the current node plus both subtree counts.", "The null subtree contributes zero, making leaves count as one."],
            ["Easy", "Find the maximum tree value", "Implement maxTreeValue(root) for a non-empty binary tree of finite numbers. Return the maximum across both subtrees; reject an empty root.", "Values 4, 9, 2 return 9.", "All-negative values still return the largest negative value rather than zero.", "function maxTreeValue(node) { if(!node)throw RangeError('Tree is empty');return Math.max(node.value,node.left?maxTreeValue(node.left):-Infinity,node.right?maxTreeValue(node.right):-Infinity); }", "O(n) time and O(h) recursion stack.", "Compare the node with the maximum from each existing subtree.", "Use negative infinity for a missing child so negative values remain correct."],
            ["Easy", "Return a preorder traversal", "Implement preorder(root) returning values in node-left-right order for a binary tree. Do not mutate nodes.", "A root 1 with left 2 and right 3 returns [1,2,3].", "null returns [].", "function preorder(root) { const out=[];function visit(node){if(!node)return;out.push(node.value);visit(node.left);visit(node.right);}visit(root);return out; }", "O(n) time and O(n) output plus O(h) recursion.", "Visit the current node before traversing either child.", "Append into one shared output array to keep traversal linear even for a skewed tree."],
            ["Medium", "Check whether a tree is height-balanced", "Implement isBalanced(root) returning true when every node's left and right subtree heights differ by at most one. Avoid recomputing subtree heights at every node.", "A complete three-node tree is balanced.", "A chain of three nodes is not balanced; empty tree is balanced.", "function isBalanced(root) { function height(n){if(!n)return 0;const l=height(n.left);if(l<0)return -1;const r=height(n.right);if(r<0||Math.abs(l-r)>1)return -1;return 1+Math.max(l,r);}return height(root)>=0; }", "O(n) time and O(h) stack.", "Return a sentinel failure height as soon as a subtree is unbalanced.", "Compute each node height once while propagating balance information upward."],
            ["Medium", "Find the lowest common ancestor in a BST", "Given a binary search tree and two values known to exist, implement lowestCommonAncestor(root,a,b). Use BST ordering to descend until the current node lies between the two values.", "In BST 6 with branches 2 and 8, LCA(2,8) is 6.", "When one value is ancestor of the other, return that ancestor.", "function lowestCommonAncestor(root,a,b) { let n=root;while(n){if(a<n.value&&b<n.value)n=n.left;else if(a>n.value&&b>n.value)n=n.right;else return n;}return null; }", "O(h) time and O(1) extra space.", "If both targets are smaller, move left; if both larger, move right.", "The first split point is the lowest common ancestor."],
            ["Medium", "Serialize and deserialize a binary tree", "Implement preorder serialization with '#' null markers and a matching deserializer. The format must preserve tree shape, including duplicate node values.", "A tree with root 1 and left child 1 round-trips to the same structure.", "null serializes to '#'; truncated or extra tokens are rejected.", "function serialize(root) { if(!root)return '#';return `${root.value},${serialize(root.left)},${serialize(root.right)}`; }\nfunction deserialize(text) { const t=text.split(','),state={i:0};function read(){if(state.i>=t.length)throw Error('Truncated');const x=t[state.i++];if(x==='#')return null;const node={value:Number(x),left:null,right:null};node.left=read();node.right=read();return node;}const root=read();if(state.i!==t.length)throw Error('Extra tokens');return root; }", "O(n) time and O(n) serialized data; O(h) recursion stack.", "Null markers encode missing child positions unambiguously.", "Deserialize in the same preorder sequence and verify all tokens are consumed."],
            ["Hard", "Construct a tree from preorder and inorder", "Given unique values in preorder and inorder traversals, reconstruct the binary tree. Use an index map for inorder positions and a preorder cursor; reject inconsistent traversals.", "preorder [3,9,20,15,7], inorder [9,3,15,20,7] rebuilds root 3.", "Empty traversals return null; mismatched value sets are rejected.", "function buildTree(pre,inorder) { if(pre.length!==inorder.length)throw Error('Invalid traversals');const pos=new Map(inorder.map((x,i)=>[x,i]));let p=0;function build(lo,hi){if(lo>hi)return null;const value=pre[p++],mid=pos.get(value);if(mid===undefined||mid<lo||mid>hi)throw Error('Inconsistent traversals');return {value,left:build(lo,mid-1),right:build(mid+1,hi)};}const root=build(0,inorder.length-1);if(p!==pre.length)throw Error('Extra values');return root; }", "O(n) time and O(n) space for the index map and tree.", "The next preorder value is the root; its inorder index divides left and right ranges.", "Advance one preorder cursor and recursively build disjoint inorder intervals."],
            ["Hard", "Find the diameter of a binary tree", "Implement treeDiameter(root) measured in number of edges on the longest path between any two nodes. Compute height and best diameter in one postorder traversal.", "A three-node chain has diameter 2.", "null and a single node have diameter 0.", "function treeDiameter(root) { let best=0;function height(n){if(!n)return 0;const l=height(n.left),r=height(n.right);best=Math.max(best,l+r);return 1+Math.max(l,r);}height(root);return best; }", "O(n) time and O(h) recursion stack.", "At each node, a path through it has left height plus right height edges.", "Update a shared best value while returning the height needed by the parent."],
            ["Hard", "Find the maximum path sum in a binary tree", "A path may start and end at any nodes but cannot reuse an edge. Implement maxPathSum(root) for a non-empty tree of positive and negative values; ignore negative child contributions when extending upward.", "Tree [-10,9,20,15,7] returns 42.", "A tree containing one negative node returns that node's value.", "function maxPathSum(root) { if(!root)throw RangeError();let best=-Infinity;function gain(n){if(!n)return 0;const l=Math.max(0,gain(n.left)),r=Math.max(0,gain(n.right));best=Math.max(best,n.value+l+r);return n.value+Math.max(l,r);}gain(root);return best; }", "O(n) time and O(h) stack.", "The global best may use both child gains, while a parent can receive only one branch.", "Clamp negative gains to zero but initialize best to negative infinity for all-negative trees."],
        ]
    },
    "Binary Search": {
        hints: ["First state the sorted-order invariant and whether the answer is a value or an insertion boundary.", "Use a half-open interval when possible; prove that every iteration shrinks it and test duplicates and empty inputs."],
        items: [
            ["Easy", "Find a value in a sorted inventory", "Implement binarySearch(values,target) for ascending integers. Return any matching index or -1, using logarithmic comparisons rather than scanning the inventory.", "[1,3,7,9], target 7 => 2.", "Empty input and targets outside the range return -1; a single matching item returns 0.", "function binarySearch(a,t) { let l=0,r=a.length-1;while(l<=r){const m=l+Math.floor((r-l)/2);if(a[m]===t)return m;if(a[m]<t)l=m+1;else r=m-1;}return -1; }", "O(log n) time and O(1) extra space.", "Compare the middle item and discard the half that cannot contain the target.", "The inclusive interval [l,r] shrinks on every branch; crossing bounds proves absence."],
            ["Easy", "Find a word in a sorted directory", "Implement findContact(names,target) for a case-sensitive, lexicographically sorted array of unique names. Return the index or -1 and describe how comparisons differ from numeric search only in type, not ordering.", "['Asha','Dev','Mina'], 'Dev' => 1.", "A target before the first or after the last name returns -1.", "function findContact(a,t) { let lo=0,hi=a.length;while(lo<hi){const mid=lo+Math.floor((hi-lo)/2);if(a[mid]<t)lo=mid+1;else hi=mid;}return lo<a.length&&a[lo]===t?lo:-1; }", "O(log n) comparisons and O(1) extra space.", "Use the same order relation used to build the sorted directory.", "A lower-bound search locates the only possible matching position, then one equality check decides."],
            ["Easy", "Find the insertion slot for a score", "Implement lowerBound(scores,newScore) that returns the first index whose value is at least newScore in an ascending score list. This is the stable insertion point before equal scores.", "[10,20,20,40], 20 => 1.", "Values below all entries return 0; above all entries return length.", "function lowerBound(a,t) { let l=0,r=a.length;while(l<r){const m=l+Math.floor((r-l)/2);if(a[m]<t)l=m+1;else r=m;}return l; }", "O(log n) time and O(1) space.", "Maintain a half-open search interval and move left when the middle can be the first valid answer.", "At termination l is the boundary between values below target and values at least target."],
            ["Medium", "Find the first and last occurrence", "Implement equalRange(values,target) for a sorted array with duplicates. Return [first,last] inclusive, or [-1,-1] when absent, using two binary searches rather than a linear scan.", "[1,2,2,2,5], 2 => [1,3].", "[] and a missing value return [-1,-1]; a single occurrence returns [i,i].", "function equalRange(a,t) { const bound=(upper)=>{let l=0,r=a.length;while(l<r){const m=l+Math.floor((r-l)/2);if(a[m]<t||(upper&&a[m]===t))l=m+1;else r=m;}return l;};const first=bound(false),after=bound(true);return first===after?[-1,-1]:[first,after-1]; }", "O(log n) time and O(1) space.", "Find the first value not less than target, then the first value greater than target.", "The two half-open boundaries delimit the complete equal-value interval."],
            ["Medium", "Find a peak in a mountain array", "Given an array that strictly increases to one peak then strictly decreases, implement peakIndex(values) in O(log n). Compare middle with its right neighbor to decide which slope still contains the peak.", "[1,4,8,6,2] => 2.", "A valid array has at least three values; a peak at either interior boundary is handled.", "function peakIndex(a) { let l=0,r=a.length-1;while(l<r){const m=l+Math.floor((r-l)/2);if(a[m]<a[m+1])l=m+1;else r=m;}return l; }", "O(log n) time and O(1) space.", "An ascending slope means the peak lies strictly to the right; otherwise it is at m or left.", "The interval converges to the unique index whose neighbors are lower."],
            ["Medium", "Search a rotated sorted list", "Implement rotatedSearch(values,target) for a strictly increasing array rotated at an unknown pivot. Return the index or -1 in O(log n), identifying which half remains sorted on every iteration.", "[6,8,10,1,3,4], target 3 => 4.", "Empty input returns -1; a target equal to the pivot-side endpoint is found.", "function rotatedSearch(a,t) { let l=0,r=a.length-1;while(l<=r){const m=l+Math.floor((r-l)/2);if(a[m]===t)return m;if(a[l]<=a[m]){if(a[l]<=t&&t<a[m])r=m-1;else l=m+1;}else{if(a[m]<t&&t<=a[r])l=m+1;else r=m-1;}}return -1; }", "O(log n) time and O(1) space under the distinct-value contract.", "At least one side around the midpoint is sorted; test whether target lies in its closed/open range.", "Discard the other side only after proving it cannot contain the target."],
            ["Hard", "Find the minimum feasible service capacity", "A warehouse must ship ordered package weights within D days, preserving order. Implement minCapacity(weights,D) using binary search on the answer, with a feasibility scan that counts days for a proposed capacity.", "[1,2,3,1,1], D=4 => 3.", "D must be positive and at least the package count; weights must be positive integers.", "function minCapacity(w,D) { if(!w.length||D<w.length)throw RangeError();let l=Math.max(...w),r=w.reduce((s,x)=>s+x,0);const fits=(cap)=>{let days=1,load=0;for(const x of w){if(load+x>cap){days++;load=0;}load+=x;}return days<=D;};while(l<r){const m=l+Math.floor((r-l)/2);if(fits(m))r=m;else l=m+1;}return l; }", "O(n log S) time for sum range S and O(1) extra space.", "The minimum possible capacity is the heaviest package; the total weight is always sufficient.", "Feasibility is monotone: if capacity c works, every larger capacity works; search for the first true value."],
            ["Hard", "Find the median of two sorted streams", "Implement medianOfSorted(a,b) in O(log(min(m,n))) time without merging. Partition both arrays so the left side contains half the values and every left value is no greater than every right value.", "[1,3] and [2] => 2; [1,2] and [3,4] => 2.5.", "One input may be empty; both empty is invalid.", "function medianOfSorted(a,b) { if(a.length>b.length)return medianOfSorted(b,a);const m=a.length,n=b.length;if(!n)throw RangeError();let lo=0,hi=m;while(lo<=hi){const i=Math.floor((lo+hi)/2),j=Math.floor((m+n+1)/2)-i;const al=i? a[i-1]:-Infinity,ar=i<m?a[i]:Infinity,bl=j?b[j-1]:-Infinity,br=j<n?b[j]:Infinity;if(al<=br&&bl<=ar)return (m+n)%2?Math.max(al,bl):(Math.max(al,bl)+Math.min(ar,br))/2;if(al>br)hi=i-1;else lo=i+1;}throw Error('Inputs must be sorted'); }", "O(log(min(m,n))) time and O(1) space.", "Binary search the shorter array's partition and derive the other partition from the desired left size.", "The cross-boundary inequalities prove the partition; use infinities at array edges."],
            ["Hard", "Find the smallest divisor under a threshold", "Given positive integers and threshold T, find the smallest positive divisor d such that the sum of ceil(value/d) is at most T. Use monotone binary search and avoid overflowing intermediate arithmetic in fixed-width languages.", "[1,2,5,9], T=6 => 5.", "T must be at least the number of values; empty input is invalid.", "function smallestDivisor(a,T) { if(!a.length||T<a.length)throw RangeError();let l=1,r=Math.max(...a);const ok=(d)=>a.reduce((sum,x)=>sum+Math.ceil(x/d),0)<=T;while(l<r){const m=l+Math.floor((r-l)/2);if(ok(m))r=m;else l=m+1;}return l; }", "O(n log M) time where M is the maximum value; O(1) extra space.", "The maximum value is feasible when T is at least the item count; smaller divisors never reduce the rounded sum.", "Search the first divisor whose monotone feasibility predicate is true."],
        ]
    },
    Heaps: {
        hints: ["Decide whether the next needed item is a minimum or maximum, then encode that ordering in the heap comparator.", "Track the heap invariant after every swap and test duplicate priorities and equal values."],
        items: [
            ["Easy", "Return the k largest scores", "Implement kLargest(scores,k) by maintaining a min-heap of at most k values. Return the selected values in descending order without sorting the full input.", "[4,1,9,3,7], k=2 => [9,7].", "k=0 returns []; k greater than input length returns all scores sorted descending.", "function kLargest(a,k) { if(!Number.isInteger(k)||k<0)throw RangeError();const heap=[];const push=x=>{heap.push(x);let i=heap.length-1;while(i){const p=(i-1)>>1;if(heap[p]<=heap[i])break;[heap[p],heap[i]]=[heap[i],heap[p]];i=p;}};const pop=()=>{const root=heap[0],last=heap.pop();if(heap.length){heap[0]=last;let i=0;while(true){let c=2*i+1;if(c>=heap.length)break;if(c+1<heap.length&&heap[c+1]<heap[c])c++;if(heap[i]<=heap[c])break;[heap[i],heap[c]]=[heap[c],heap[i]];i=c;}}return root;};for(const x of a){push(x);if(heap.length>k)pop();}return heap.sort((x,y)=>y-x); }", "O(n log k + k log k) time and O(k) heap space.", "A min-heap root is the weakest member of the current top-k set.", "Insert each value and remove the root when the heap exceeds k; then order only the retained values."],
            ["Easy", "Merge two sorted task queues", "Implement mergeSorted(a,b) that combines two ascending arrays into a new ascending array in linear time. Use indices and append the unconsumed suffix when one input ends.", "[1,4,8] and [2,3] => [1,2,3,4,8].", "Either input may be empty; equal values from both inputs are preserved.", "function mergeSorted(a,b) { let i=0,j=0,out=[];while(i<a.length&&j<b.length)out.push(a[i]<=b[j]?a[i++]:b[j++]);return out.concat(a.slice(i),b.slice(j)); }", "O(n+m) time and O(n+m) output space.", "The smallest unconsumed item must be the next output because each source is sorted.", "Advance only the pointer whose value was emitted; append the remainder after one source ends."],
            ["Easy", "Find the kth smallest item", "Implement kthSmallest(values,k) with a max-heap of size k so the heap root is the kth-smallest candidate after processing the input.", "[7,2,9,4], k=2 => 4.", "Reject k below 1 or greater than the input length; duplicates count as separate positions.", "function kthSmallest(a,k) { if(!Number.isInteger(k)||k<1||k>a.length)throw RangeError();const h=[];const push=x=>{h.push(x);let i=h.length-1;while(i){const p=(i-1)>>1;if(h[p]>=h[i])break;[h[p],h[i]]=[h[i],h[p]];i=p;}};const pop=()=>{const root=h[0],last=h.pop();if(h.length){h[0]=last;let i=0;while(true){let c=2*i+1;if(c>=h.length)break;if(c+1<h.length&&h[c+1]>h[c])c++;if(h[i]>=h[c])break;[h[i],h[c]]=[h[c],h[i]];i=c;}}return root;};for(const x of a){if(h.length<k)push(x);else if(x<h[0]){pop();push(x);}}return h[0]; }", "O(n log k) time and O(k) space.", "A max-heap of the k smallest seen values exposes the largest retained candidate.", "Replace the root only when a smaller value arrives; after all values, the root is kth smallest."],
            ["Medium", "Maintain a live median", "Design MedianTracker with add(value) and median() using a max-heap for the lower half and a min-heap for the upper half. Rebalance so sizes differ by at most one and all lower values are no greater than upper values.", "Add 5, 1, 9 => medians 5, 3, 5.", "median() on an empty tracker throws; duplicate values are accepted.", "// Maintain lowerMax.size === upperMin.size or one larger; move roots to rebalance after each insertion.", "O(log n) insertion, O(1) median read, O(n) storage.", "Insert relative to the lower heap root, then rebalance by moving one root if sizes differ by two.", "For odd count read the larger heap root; for even count average both roots."],
            ["Medium", "Merge k sorted event streams", "Implement mergeKSorted(streams) for k ascending arrays. Use a min-heap of each stream's current head, storing value, stream index, and offset; emit a head then insert its successor.", "[[1,4],[1,3],[2]] => [1,1,2,3,4].", "Empty streams are allowed; all-empty input returns [].", "// Heap entries compare by value, then stream index for deterministic ties. Seed one entry per nonempty stream; repeatedly pop, emit, and push that stream's next item.", "O(N log k) time and O(k) heap space for N total values.", "Only one candidate per stream can be the next global value: its current head.", "Pop the smallest candidate and advance just that source, preserving sorted output."],
            ["Medium", "Schedule the most urgent jobs", "Given jobs with release order and integer priority, implement a priority queue that always removes the highest priority, breaking ties by earlier sequence number. Specify comparator behavior and stable results.", "Priorities 3(seq 0), 5(seq 1), 5(seq 2) pop seq 1, then seq 2, then seq 0.", "An empty pop returns undefined; negative priorities are valid.", "// Compare a before b when a.priority>b.priority, or priorities tie and a.sequence<b.sequence; maintain this comparator in heap swim/sink operations.", "O(log n) insertion/removal and O(n) storage.", "Encode tie-breaking in a total comparator rather than relying on runtime sort stability.", "Use the same comparator in every parent-child invariant check."],
            ["Hard", "Find the smallest range covering all streams", "Given k sorted lists, find the inclusive smallest numeric range containing at least one value from every list. Use a min-heap of current heads and track the maximum head seen; advance the list owning the minimum.", "[[4,10,15],[1,8,12],[7,8,20]] => [7,8].", "A list may contain one value; any empty list makes a covering range impossible.", "// Seed heap with each list's first value and currentMax. Repeatedly compare [heapMin,currentMax], retain the narrower range, then advance the min's list; stop when that list ends.", "O(N log k) time and O(k) auxiliary space.", "The current heads define a valid covering range; advancing the minimum is the only move that can improve its lower endpoint.", "Stop when one stream is exhausted because no later range can include that stream's next value."],
            ["Hard", "Combine ropes at minimum total cost", "Given rope lengths, combine two ropes at a time; each join costs the sum of lengths. Implement minimumJoinCost using a min-heap and return total cost.", "[4,3,2,6] => 29 by joins 2+3, 4+5, 6+9.", "One rope costs 0; empty input costs 0; nonpositive lengths are rejected.", "function minimumJoinCost(a) { if(a.some(x=>!Number.isFinite(x)||x<=0))throw RangeError();const h=[];const push=x=>{h.push(x);let i=h.length-1;while(i){const p=(i-1)>>1;if(h[p]<=h[i])break;[h[p],h[i]]=[h[i],h[p]];i=p;}};const pop=()=>{const root=h[0],last=h.pop();if(h.length){h[0]=last;let i=0;while(true){let c=2*i+1;if(c>=h.length)break;if(c+1<h.length&&h[c+1]<h[c])c++;if(h[i]<=h[c])break;[h[i],h[c]]=[h[c],h[i]];i=c;}}return root;};for(const x of a)push(x);let cost=0;while(h.length>1){const sum=pop()+pop();cost+=sum;push(sum);}return cost; }", "O(n log n) time and O(n) heap space.", "The two shortest available ropes should be joined first; each joined result returns as a new candidate.", "Repeatedly extract two minima, add their sum to cost, and insert that sum."],
            ["Hard", "Maintain the kth largest in a live stream", "Implement KthLargest(k,initial) with add(value) returning the kth-largest value seen so far. Keep only a min-heap of the largest k values; before k values exist, define the result as null.", "k=3, initial=[4,5,8,2]; add(3)=>4, add(5)=>5.", "k must be positive; duplicate values occupy separate ranks.", "// On add, push into a min-heap; if size exceeds k, remove the minimum. Return heap root only when size===k, otherwise null.", "O(log k) per update and O(k) space.", "The heap contains exactly the best k values seen so far once enough values exist.", "The root is the smallest among those retained values, hence the kth largest overall."],
        ]
    },
};

const slug = (value) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const exampleFor = (text, label) => {
    const parts = text.split(" => ");
    return {
        input: parts.length > 1 ? parts[0] : `${label}: ${text}`,
        output: parts.length > 1 ? parts.slice(1).join(" => ") : text,
        explanation: label === "Representative" ? "Apply the stated operation to the supplied input." : "Use the boundary or failure condition to check the contract."
    };
};

export const FULL_STACK_DSA_PRACTICE_EXERCISES = Object.fromEntries(
    Object.entries(dsaCases).map(([topic, data]) => [topic, data.items.map(([difficulty, title, problem, expected, edgeCase, solutionCode, complexity, approach, walkthrough], index) => ({
        id: `fs-dsa-${slug(topic)}-${difficulty.toLowerCase()}-${index + 1}-v1`,
        career: "Full Stack Developer",
        phase: "DSA",
        topic,
        title,
        difficulty,
        estimatedTime: difficulty === "Easy" ? "20–30 minutes" : difficulty === "Medium" ? "35–50 minutes" : "50–75 minutes",
        kind: "coding",
        language: "JavaScript",
        simplerProblem: `Work through one ${topic} case using a small input before scaling up.`,
        problemStatement: `${problem} State your invariant, justify the chosen strategy, and explain its time and space costs.`,
        requirements: [
            `Implement the stated ${topic} behavior without mutating inputs unless explicitly allowed.`,
            "Document assumptions and return behavior for invalid, empty, and boundary inputs.",
            "Use the required algorithmic strategy and justify why it satisfies expected complexity."
        ],
        examples: [exampleFor(expected, "Representative"), exampleFor(edgeCase, "Boundary")],
        tests: [
            { name: "Representative case", ...exampleFor(expected, "Representative"), expected: exampleFor(expected, "Representative").output },
            { name: "Boundary case", ...exampleFor(edgeCase, "Boundary"), expected: exampleFor(edgeCase, "Boundary").output }
        ],
        hints: data.hints,
        learningObjectives: [`Apply ${topic} to a concrete problem with stated constraints.`, "Test ordinary and boundary inputs and explain correctness."],
        conceptsToReview: [topic, "Algorithm invariants", "Time and space complexity"],
        prerequisites: [],
        approach: `${approach} At each step, preserve the stated invariant, update only after checking the current input, and verify termination at the boundary case.`,
        walkthrough: `${walkthrough} Example check: ${expected} Boundary check: ${edgeCase}`,
        solutionCode: solutionCode.length >= 60 ? solutionCode : `${solutionCode}\n// Check the representative result and the stated boundary before accepting the implementation.`,
        solutionLines: [approach, walkthrough, complexity, solutionCode],
        complexity,
        commonMistakes: ["Skipping empty-input or duplicate-value behavior stated in the contract.", "Claiming a better complexity than the chosen data structure provides."],
        followUp: `Adapt the ${topic} solution to return the actual indices or decisions, not only the final value.`,
        completionCriteria: ["The implementation matches both examples.", "The boundary case is handled safely.", "The invariant and complexity claim are explained."],
        starterCode: `function solve(input) {\n  // ${topic}: identify the invariant and boundary behavior\n}\n`
    }))])
);
